// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /admin/v1/admins)
	ListAdmins(ctx context.Context, request ListAdminsRequestObject) (ListAdminsResponseObject, error)
	// 新建管理员，返回一次性初始密码
	// (POST /admin/v1/admins)
	CreateAdmin(ctx context.Context, request CreateAdminRequestObject) (CreateAdminResponseObject, error)

	// (PATCH /admin/v1/admins/{adminId})
	UpdateAdmin(ctx context.Context, request UpdateAdminRequestObject) (UpdateAdminResponseObject, error)
	// 重置密码，返回一次性新密码
	// (POST /admin/v1/admins/{adminId}/reset-password)
	ResetAdminPassword(ctx context.Context, request ResetAdminPasswordRequestObject) (ResetAdminPasswordResponseObject, error)
	// 成本与额度：总成本和每活跃用户成本、单次任务成本分布、本月额度用量
	// (GET /admin/v1/analytics/costs)
	GetAnalyticsCosts(ctx context.Context, request GetAnalyticsCostsRequestObject) (GetAnalyticsCostsResponseObject, error)
	// 功能使用：简报、模板排行、报告、推送触达
	// (GET /admin/v1/analytics/engagement)
	GetAnalyticsEngagement(ctx context.Context, request GetAnalyticsEngagementRequestObject) (GetAnalyticsEngagementResponseObject, error)
	// 用户增长：每日新增（按登录方式）和活跃、平台/版本/语言分布、激活漏斗
	// (GET /admin/v1/analytics/growth)
	GetAnalyticsGrowth(ctx context.Context, request GetAnalyticsGrowthRequestObject) (GetAnalyticsGrowthResponseObject, error)
	// 核心指标：门槛 B 三项、DAU/WAU/MAU（较前一周期）、待办、近 30 天活跃与新增、流失预警
	// (GET /admin/v1/analytics/overview)
	GetAnalyticsOverview(ctx context.Context, request GetAnalyticsOverviewRequestObject) (GetAnalyticsOverviewResponseObject, error)
	// 任务质量：按类型的失败率和耗时、失败原因 Top 10
	// (GET /admin/v1/analytics/quality)
	GetAnalyticsQuality(ctx context.Context, request GetAnalyticsQualityRequestObject) (GetAnalyticsQualityResponseObject, error)
	// 留存：按注册周的同期群（from/to 是注册日期范围，默认近 12 周）
	// (GET /admin/v1/analytics/retention)
	GetAnalyticsRetention(ctx context.Context, request GetAnalyticsRetentionRequestObject) (GetAnalyticsRetentionResponseObject, error)
	// 审计日志
	// (GET /admin/v1/audit-log)
	ListAuditLog(ctx context.Context, request ListAuditLogRequestObject) (ListAuditLogResponseObject, error)
	// 邮箱密码登录
	// (POST /admin/v1/auth/login)
	AdminLogin(ctx context.Context, request AdminLoginRequestObject) (AdminLoginResponseObject, error)
	// 运营推送活动，按创建时间倒序
	// (GET /admin/v1/campaigns)
	ListCampaigns(ctx context.Context, request ListCampaignsRequestObject) (ListCampaignsResponseObject, error)
	// 新建草稿
	// (POST /admin/v1/campaigns)
	CreateCampaign(ctx context.Context, request CreateCampaignRequestObject) (CreateCampaignResponseObject, error)
	// 估算目标人数
	// (POST /admin/v1/campaigns/audience-estimate)
	EstimateCampaignAudience(ctx context.Context, request EstimateCampaignAudienceRequestObject) (EstimateCampaignAudienceResponseObject, error)
	// 删除草稿
	// (DELETE /admin/v1/campaigns/{campaignId})
	DeleteCampaign(ctx context.Context, request DeleteCampaignRequestObject) (DeleteCampaignResponseObject, error)
	// 详情和送达统计
	// (GET /admin/v1/campaigns/{campaignId})
	GetCampaign(ctx context.Context, request GetCampaignRequestObject) (GetCampaignResponseObject, error)
	// 修改草稿（被驳回的活动回到草稿）
	// (PUT /admin/v1/campaigns/{campaignId})
	UpdateCampaign(ctx context.Context, request UpdateCampaignRequestObject) (UpdateCampaignResponseObject, error)
	// 审批通过（仅 owner）。没有定时则立即开始发送
	// (POST /admin/v1/campaigns/{campaignId}/approve)
	ApproveCampaign(ctx context.Context, request ApproveCampaignRequestObject) (ApproveCampaignResponseObject, error)
	// 取消待审批、已排期或发送中的活动；已写入的消息保留，可再撤回
	// (POST /admin/v1/campaigns/{campaignId}/cancel)
	CancelCampaign(ctx context.Context, request CancelCampaignRequestObject) (CancelCampaignResponseObject, error)
	// 撤回：从所有用户的消息中心移除（已送达的推送无法撤回）
	// (POST /admin/v1/campaigns/{campaignId}/recall)
	RecallCampaign(ctx context.Context, request RecallCampaignRequestObject) (RecallCampaignResponseObject, error)
	// 驳回，回到草稿（仅 owner）
	// (POST /admin/v1/campaigns/{campaignId}/reject)
	RejectCampaign(ctx context.Context, request RejectCampaignRequestObject) (RejectCampaignResponseObject, error)
	// 提交审批（草稿 → 待审批）
	// (POST /admin/v1/campaigns/{campaignId}/submit)
	SubmitCampaign(ctx context.Context, request SubmitCampaignRequestObject) (SubmitCampaignResponseObject, error)
	// 发测试推送到指定 App 用户的设备（标题加「[测试]」，不进消息中心，不受频控）
	// (POST /admin/v1/campaigns/{campaignId}/test-send)
	TestSendCampaign(ctx context.Context, request TestSendCampaignRequestObject) (TestSendCampaignResponseObject, error)
	// 工作副本相对线上版本的改动（发布前的 diff）
	// (GET /admin/v1/config/changes)
	ListConfigChanges(ctx context.Context, request ListConfigChangesRequestObject) (ListConfigChangesResponseObject, error)
	// 配置项（工作副本），附线上版本的值
	// (GET /admin/v1/config/keys)
	ListConfigKeys(ctx context.Context, request ListConfigKeysRequestObject) (ListConfigKeysResponseObject, error)
	// 新建配置项（owner）。新建后要发布才会下发
	// (POST /admin/v1/config/keys)
	CreateConfigKey(ctx context.Context, request CreateConfigKeyRequestObject) (CreateConfigKeyResponseObject, error)

	// (GET /admin/v1/config/keys/{key})
	GetConfigKey(ctx context.Context, request GetConfigKeyRequestObject) (GetConfigKeyResponseObject, error)
	// 修改工作副本。改命名空间、归档需要 owner；类型不能改
	// (PATCH /admin/v1/config/keys/{key})
	UpdateConfigKey(ctx context.Context, request UpdateConfigKeyRequestObject) (UpdateConfigKeyResponseObject, error)
	// 某个用户 / 设备会拿到什么值、命中哪条规则
	// (POST /admin/v1/config/preview)
	PreviewConfig(ctx context.Context, request PreviewConfigRequestObject) (PreviewConfigResponseObject, error)
	// 发布记录，最新在前
	// (GET /admin/v1/config/releases)
	ListConfigReleases(ctx context.Context, request ListConfigReleasesRequestObject) (ListConfigReleasesResponseObject, error)
	// 提交发布。按审批规则直接上线（status=published）或等待审批（status=pending）
	// (POST /admin/v1/config/releases)
	SubmitConfigRelease(ctx context.Context, request SubmitConfigReleaseRequestObject) (SubmitConfigReleaseResponseObject, error)
	// 发布详情。已发布的与上一个发布版本比较，待审批的与当前线上版本比较
	// (GET /admin/v1/config/releases/{releaseId})
	GetConfigRelease(ctx context.Context, request GetConfigReleaseRequestObject) (GetConfigReleaseResponseObject, error)
	// 审批并上线（owner；不能审批自己提交的，除非只有一个 owner）
	// (POST /admin/v1/config/releases/{releaseId}/approve)
	ApproveConfigRelease(ctx context.Context, request ApproveConfigReleaseRequestObject) (ApproveConfigReleaseResponseObject, error)
	// 驳回待审批的发布（owner）
	// (POST /admin/v1/config/releases/{releaseId}/reject)
	RejectConfigRelease(ctx context.Context, request RejectConfigReleaseRequestObject) (RejectConfigReleaseResponseObject, error)
	// 把这个已发布版本的内容作为新版本重新发布，同时把工作副本恢复成它（审批规则同提交）
	// (POST /admin/v1/config/releases/{releaseId}/rollback)
	RollbackConfigRelease(ctx context.Context, request RollbackConfigReleaseRequestObject) (RollbackConfigReleaseResponseObject, error)
	// 内置工具与 MCP 白名单（含已下架）
	// (GET /admin/v1/connectors)
	ListConnectors(ctx context.Context, request ListConnectorsRequestObject) (ListConnectorsResponseObject, error)
	// 上下架、默认开启、排序与展示文案。新增 MCP 服务需要改代码（catalog.yaml）后发布
	// (PATCH /admin/v1/connectors/{connectorId})
	UpdateConnector(ctx context.Context, request UpdateConnectorRequestObject) (UpdateConnectorResponseObject, error)
	// 成本：按天、按模型、按任务类型、最高成本用户
	// (GET /admin/v1/costs)
	GetCosts(ctx context.Context, request GetCostsRequestObject) (GetCostsResponseObject, error)
	// 运营概览（按 Asia/Shanghai 计日）
	// (GET /admin/v1/dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// 用户意见反馈
	// (GET /admin/v1/feedback)
	ListFeedback(ctx context.Context, request ListFeedbackRequestObject) (ListFeedbackResponseObject, error)

	// (GET /admin/v1/feedback/{feedbackId})
	GetFeedback(ctx context.Context, request GetFeedbackRequestObject) (GetFeedbackResponseObject, error)
	// 改状态、写内部备注（用户看不到备注）
	// (PATCH /admin/v1/feedback/{feedbackId})
	UpdateFeedback(ctx context.Context, request UpdateFeedbackRequestObject) (UpdateFeedbackResponseObject, error)
	// 回复用户。用户在「我的反馈」里看到并收到推送（zeus://feedback/{id}）；待处理的反馈自动转为处理中
	// (POST /admin/v1/feedback/{feedbackId}/replies)
	ReplyFeedback(ctx context.Context, request ReplyFeedbackRequestObject) (ReplyFeedbackResponseObject, error)
	// 当前管理员
	// (GET /admin/v1/me)
	GetAdminMe(ctx context.Context, request GetAdminMeRequestObject) (GetAdminMeResponseObject, error)
	// 修改自己的密码
	// (POST /admin/v1/me/password)
	ChangeAdminPassword(ctx context.Context, request ChangeAdminPasswordRequestObject) (ChangeAdminPasswordResponseObject, error)
	// 去掉手动价格，恢复按同步价（或内置目录）计费（仅 owner）
	// (DELETE /admin/v1/model-prices)
	ClearModelPrice(ctx context.Context, request ClearModelPriceRequestObject) (ClearModelPriceResponseObject, error)
	// 百炼模型定价（同步自百炼的价格 + 后台手动价；没同步过时用服务端内置目录）
	// (GET /admin/v1/model-prices)
	ListModelPrices(ctx context.Context, request ListModelPricesRequestObject) (ListModelPricesResponseObject, error)
	// 手动设置一个模型的价格（仅 owner），之后同步不会覆盖，约 1 分钟内用于计费
	// (PUT /admin/v1/model-prices)
	SetModelPrice(ctx context.Context, request SetModelPriceRequestObject) (SetModelPriceResponseObject, error)
	// 从百炼实时拉取全部文本模型和价格（仅 owner）；手动价格保留
	// (POST /admin/v1/model-prices/sync)
	SyncModelPrices(ctx context.Context, request SyncModelPricesRequestObject) (SyncModelPricesResponseObject, error)
	// 各档位和各环节用哪个模型（路由文件默认值 + 后台指定）
	// (GET /admin/v1/model-routing)
	GetModelRouting(ctx context.Context, request GetModelRoutingRequestObject) (GetModelRoutingResponseObject, error)
	// 用这个服务商当前的 Key 实时拉取可用模型（GET /models）
	// (GET /admin/v1/model-routing/providers/{provider}/models)
	ListProviderModels(ctx context.Context, request ListProviderModelsRequestObject) (ListProviderModelsResponseObject, error)
	// 用当前 Key 调一次指定模型（仅 owner），输出 1 个 token
	// (POST /admin/v1/model-routing/test)
	TestModel(ctx context.Context, request TestModelRequestObject) (TestModelResponseObject, error)
	// 恢复路由文件的默认值（仅 owner）
	// (DELETE /admin/v1/model-routing/{scope})
	DeleteModelOverride(ctx context.Context, request DeleteModelOverrideRequestObject) (DeleteModelOverrideResponseObject, error)
	// 指定档位或环节的模型（仅 owner），约 1 分钟内生效
	// (PUT /admin/v1/model-routing/{scope})
	SetModelOverride(ctx context.Context, request SetModelOverrideRequestObject) (SetModelOverrideResponseObject, error)
	// 模型网关路由与单价（读自 ZEUS_MODELGW_CONFIG，只读；修改需改文件并重启）及近 24 小时调用
	// (GET /admin/v1/modelgw)
	GetModelGateway(ctx context.Context, request GetModelGatewayRequestObject) (GetModelGatewayResponseObject, error)
	// 拦截记录
	// (GET /admin/v1/moderation/events)
	ListModerationEvents(ctx context.Context, request ListModerationEventsRequestObject) (ListModerationEventsResponseObject, error)
	// 屏蔽词（与 ZEUS_MODERATION_KEYWORDS_FILE 合并生效，约 1 分钟内同步到各进程）
	// (GET /admin/v1/moderation/terms)
	ListModerationTerms(ctx context.Context, request ListModerationTermsRequestObject) (ListModerationTermsResponseObject, error)

	// (POST /admin/v1/moderation/terms)
	CreateModerationTerm(ctx context.Context, request CreateModerationTermRequestObject) (CreateModerationTermResponseObject, error)

	// (DELETE /admin/v1/moderation/terms/{termId})
	DeleteModerationTerm(ctx context.Context, request DeleteModerationTermRequestObject) (DeleteModerationTermResponseObject, error)
	// 方案与额度（代码内配置，只读）
	// (GET /admin/v1/plans)
	ListPlans(ctx context.Context, request ListPlansRequestObject) (ListPlansResponseObject, error)
	// 模型和搜索服务商的 API Key（只返回末 4 位）及每个服务商当前用的是哪把
	// (GET /admin/v1/provider-keys)
	ListProviderKeys(ctx context.Context, request ListProviderKeysRequestObject) (ListProviderKeysResponseObject, error)
	// 保存一把 Key（仅 owner）。activate 为 true 时同时设为该服务商的启用 Key，约 1 分钟内各进程生效
	// (POST /admin/v1/provider-keys)
	CreateProviderKey(ctx context.Context, request CreateProviderKeyRequestObject) (CreateProviderKeyResponseObject, error)
	// 保存前测试一把 Key（仅 owner），模型发 1 个 token、搜索发一次查询
	// (POST /admin/v1/provider-keys/test)
	TestNewProviderKey(ctx context.Context, request TestNewProviderKeyRequestObject) (TestNewProviderKeyResponseObject, error)
	// 删除（仅 owner，启用中的 Key 需先停用）
	// (DELETE /admin/v1/provider-keys/{keyId})
	DeleteProviderKey(ctx context.Context, request DeleteProviderKeyRequestObject) (DeleteProviderKeyResponseObject, error)
	// 改备注或 API 地址（仅 owner），启用中的 Key 约 1 分钟内生效
	// (PATCH /admin/v1/provider-keys/{keyId})
	UpdateProviderKey(ctx context.Context, request UpdateProviderKeyRequestObject) (UpdateProviderKeyResponseObject, error)
	// 设为该服务商的启用 Key（仅 owner），同服务商其他 Key 自动停用
	// (POST /admin/v1/provider-keys/{keyId}/activate)
	ActivateProviderKey(ctx context.Context, request ActivateProviderKeyRequestObject) (ActivateProviderKeyResponseObject, error)
	// 停用（仅 owner），该服务商回退到环境变量里的 Key
	// (POST /admin/v1/provider-keys/{keyId}/deactivate)
	DeactivateProviderKey(ctx context.Context, request DeactivateProviderKeyRequestObject) (DeactivateProviderKeyResponseObject, error)
	// 测试已保存的 Key（仅 owner），结果记在这把 Key 上；不指定参数时传 {}
	// (POST /admin/v1/provider-keys/{keyId}/test)
	TestProviderKey(ctx context.Context, request TestProviderKeyRequestObject) (TestProviderKeyResponseObject, error)
	// 报告满意度评分，按最近评分排序
	// (GET /admin/v1/report-feedback)
	ListReportFeedback(ctx context.Context, request ListReportFeedbackRequestObject) (ListReportFeedbackResponseObject, error)
	// 查看报告正文（审核用）
	// (GET /admin/v1/reports/{reportId})
	GetReport(ctx context.Context, request GetReportRequestObject) (GetReportResponseObject, error)
	// 公开分享的报告和简报
	// (GET /admin/v1/shares)
	ListShares(ctx context.Context, request ListSharesRequestObject) (ListSharesResponseObject, error)
	// 撤销分享链接
	// (POST /admin/v1/shares/{shareId}/revoke)
	RevokeShare(ctx context.Context, request RevokeShareRequestObject) (RevokeShareResponseObject, error)
	// 全部任务
	// (GET /admin/v1/tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// 任务详情与模型调用明细
	// (GET /admin/v1/tasks/{taskId})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)
	// 取消运行中的任务
	// (POST /admin/v1/tasks/{taskId}/cancel)
	CancelTask(ctx context.Context, request CancelTaskRequestObject) (CancelTaskResponseObject, error)
	// 模板列表；official 为官方模板，custom 为用户自定义模板（用于审核）
	// (GET /admin/v1/templates)
	ListTemplates(ctx context.Context, request ListTemplatesRequestObject) (ListTemplatesResponseObject, error)
	// 新建官方模板
	// (POST /admin/v1/templates)
	CreateTemplate(ctx context.Context, request CreateTemplateRequestObject) (CreateTemplateResponseObject, error)
	// 删除模板（已订阅的简报保留，但与模板解除关联；官方模板建议改为下架）
	// (DELETE /admin/v1/templates/{templateId})
	DeleteTemplate(ctx context.Context, request DeleteTemplateRequestObject) (DeleteTemplateResponseObject, error)

	// (GET /admin/v1/templates/{templateId})
	GetTemplate(ctx context.Context, request GetTemplateRequestObject) (GetTemplateResponseObject, error)
	// 修改模板。官方模板改过后不再被 `zeusctl seed` 覆盖；字段、栏目或来源变化时版本号加 1
	// (PUT /admin/v1/templates/{templateId})
	UpdateTemplate(ctx context.Context, request UpdateTemplateRequestObject) (UpdateTemplateResponseObject, error)
	// 用户列表
	// (GET /admin/v1/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// 用户详情（额度、定时简报、近 30 天成本）
	// (GET /admin/v1/users/{userId})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// 修改会员方案
	// (PATCH /admin/v1/users/{userId})
	UpdateUserPlan(ctx context.Context, request UpdateUserPlanRequestObject) (UpdateUserPlanResponseObject, error)
	// 停用账号（注销登录态，暂停其定时简报）
	// (POST /admin/v1/users/{userId}/disable)
	DisableUser(ctx context.Context, request DisableUserRequestObject) (DisableUserResponseObject, error)
	// 恢复账号（恢复因停用而暂停的定时简报）
	// (POST /admin/v1/users/{userId}/enable)
	EnableUser(ctx context.Context, request EnableUserRequestObject) (EnableUserResponseObject, error)
	// 清除额度覆盖
	// (DELETE /admin/v1/users/{userId}/quota)
	ClearUserQuota(ctx context.Context, request ClearUserQuotaRequestObject) (ClearUserQuotaResponseObject, error)
	// 设置额度覆盖（字段为空表示沿用方案额度）
	// (PUT /admin/v1/users/{userId}/quota)
	SetUserQuota(ctx context.Context, request SetUserQuotaRequestObject) (SetUserQuotaResponseObject, error)
	// 给用户加赠本月 token（计入加赠当月，不结转）
	// (POST /admin/v1/users/{userId}/token-grants)
	GrantUserTokens(ctx context.Context, request GrantUserTokensRequestObject) (GrantUserTokensResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

